}

private panelDeps() {
  return {
    extensionUri: this.context.extensionUri,
    log: this.log,
    onMessage: (root: string | undefined, message: WebviewToHostMessage) => {
      this.messages.fire(message);
      this.events.fire({ root, message });
    },
