export function defaultSubjectName(folderName: string): string {
  const words = folderName.split(/[^A-Za-z0-9]+/).filter((w) => w.length > 0);
  const candidate = words.map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join('').slice(0, 64);
