      SNAP_UID: '1002',
      SNAP_COOKIE: PLACEHOLDER_COOKIE,
      SNAP_CONTEXT: PLACEHOLDER_COOKIE,
    });
    expect(env).not.toHaveProperty('HOME');
    expect(env).not.toHaveProperty('XDG_RUNTIME_DIR');
