  it('fresh model with three cards', async () => {
    const dir = makeTempDir('explore');
    const root = path.join(dir, 'demo');
    mkdirSync(root);
    const inspection = await inspectFolder(root);
    const changes = planInitialize({ subject: 'Demo', inspection });
    await fsEditApplier(root).apply(changes, 'Initialize model');
    const ws = createModelWorkspace({ root, text: fsTextSource(root), applier: fsEditApplier(root), semantic: { debounceMs: 60_000 }, now: () => new Date('2026-11-10T12:00:00Z') });
    await ws.load();
    console.log(await ws.initGit());
    for (const [type, naturalName] of [['ASSUMPTION', 'All humans are mortal'], ['ASSUMPTION', 'Socrates is a human'], ['GOAL', 'Socrates is mortal']] as const) {
      const out = await ws.perform({ kind: 'add-node', subject: 'Demo', type, naturalName });
      console.log(JSON.stringify(out));
    }
    const s = await ws.refreshNow();
    console.log(JSON.stringify(s));
    console.log(readFileSync(path.join(root, 'Model/Demo/Inbox.lean'), 'utf8'));
    console.log(ws.modelFiles());
    const graph = ws.graph('Demo');
