import { createProposalService, createRunSidecarStore } from '../../src/proposal/index.js';
import { createRunManager, DEFAULT_RUN_SETTINGS } from '../../src/run/index.js';
import { listRunDirs } from '../../src/shadow/index.js';
import { createModelWorkspace, fsEditApplier, fsTextSource, inspectFolder, planInitialize } from '../../src/workspace/index.js';
import { makeTempDir, REPO_ROOT } from './helpers/env.js';
import { waitForRun } from './helpers/harness.js';

type Fresh = FakeScriptFile & { subject: string; today: string; cards: Array<{ type: NodeType; naturalName: string }>; target: string; premises: string[]; adopt?: { ghost: string; rationale?: string } };

const NAME = process.env['FRESH_NAME'] ?? 'socrates';

describe('explore', () => {
  it(`fresh ${NAME}`, async () => {
    const file = validateFakeScriptFile(JSON.parse(readFileSync(path.join(REPO_ROOT, 'test-fixtures', 'fresh', `${NAME}.json`), 'utf8'))) as Fresh;
    const dir = makeTempDir('explore');
    const root = path.join(dir, 'demo');
    mkdirSync(root);
    const inspection = await inspectFolder(root);
    await fsEditApplier(root).apply(planInitialize({ subject: file.subject, inspection }), 'Initialize model');
    const ws = createModelWorkspace({ root, text: fsTextSource(root), applier: fsEditApplier(root), semantic: { debounceMs: 60_000 }, now: () => new Date(`${file.today}T12:00:00Z`) });
    await ws.load();
    await ws.initGit();
    for (const c of file.cards) {
      const out = await ws.perform({ kind: 'add-node', subject: file.subject, type: c.type, naturalName: c.naturalName });
      expect(out.ok).toBe(true);
    }
    await ws.refreshNow();
    const play = playFakeScript(file);
    const runsDir = path.join(dir, 'runs');
    const manager = createRunManager({
      root,
      runsDir,
      workspace: ws,
      services: { backend: new FakeBackend(play.script), engine: createLeanCheckEngine(), proposals: createProposalService(), sidecars: createRunSidecarStore() },
      settings: DEFAULT_RUN_SETTINGS,
    });
    const started = await manager.start({ subject: file.subject, target: file.target, premises: file.premises });
    console.log('START', JSON.stringify(started));
    const end = await waitForRun(manager, (v) => v.state === 'review' || v.state === 'failed' || v.state === 'waiting-for-answer', 300_000);
    console.log('STATE', end.state, end.verdict, JSON.stringify(end.notices, null, 1), end.error);
    const runDir = (await listRunDirs(runsDir, root)).find((d) => d.runId === end.runId)?.runDir ?? '';
    const events = readFileSync(path.join(runDir, 'session', 'transcript.jsonl'), 'utf8').trim().split('\n').map((l) => JSON.parse(l) as { kind: string; event?: LlmEvent });
    for (const e of events) if (e.kind === 'event' && e.event?.type === 'tool_result') console.log('TOOL RESULT\n', e.event.text);
    const proposal = manager.proposal();
    console.log('PROPOSAL', JSON.stringify({ definitions: proposal?.definitions, lifecycle: proposal?.lifecycle, report: proposal?.report, ghosts: end.ghosts }, null, 1));
    await manager.dispose();
    ws.dispose();
  });
});

