      id,
      idWritten,
      version: raw.version,
      fields: raw.fields,
      extensions: raw.extensions,
      span: raw.comment.span,
      range: lines.range(raw.comment.span),
      markerSpan: raw.markerSpan,
      lines: raw.lines,
      binding: { mode: 'none' },
    };
    if (raw.body !== undefined) block.body = raw.body;
    if (raw.bodySpan !== undefined) block.bodySpan = raw.bodySpan;
