    case 'def':
    case 'abbrev':
      return 'def';
    case 'opaque':
      return 'opaque';
    case 'instance':
      return 'instance';
    case 'structure':
      return 'structure';
    case 'inductive':
    case 'coinductive':
      return 'inductive';
    case 'class':
    case 'class inductive':
    case 'class abbrev':
      return 'class';
    default:
