// TEMPORARY exploration of honest variants a real Claude might write on a fresh model (deleted before the end).
import { mkdirSync, readFileSync } from 'node:fs';
import path from 'node:path';

import { describe, it } from 'vitest';

import { createLeanCheckEngine } from '../../src/gate/index.js';
import { FakeBackend, type FakeStep } from '../../src/llm/fake.js';
import { playFakeScript } from '../../src/llm/fakeScripts.js';
import type { LlmEvent } from '../../src/llm/types.js';
import { createProposalService, createRunSidecarStore } from '../../src/proposal/index.js';
import { createRunManager, DEFAULT_RUN_SETTINGS } from '../../src/run/index.js';
import { listRunDirs } from '../../src/shadow/index.js';
import { createModelWorkspace, fsEditApplier, fsTextSource, inspectFolder, planInitialize } from '../../src/workspace/index.js';
import { makeTempDir, REPO_ROOT } from './helpers/env.js';
import { waitForRun } from './helpers/harness.js';

const INBOX = 'Model/Demo/Inbox.lean';
const VOCAB = 'Model/Demo/Vocabulary.lean';
const MAIN = 'Model/Demo/Main.lean';
const B = (s: string, prem?: string) => `natural_name: ${s}\n${prem ? `premises: ${prem}\n` : ''}asserted: 2026-11-10\n-/\n`;
const P = 'all-humans-are-mortal, socrates-is-a-human';
const edit = (p: string, o: string, n: string): FakeStep => ({ kind: 'edit', path: p, oldString: o, newString: n });
const call = (tool: string, args: unknown): FakeStep => ({ kind: 'callTool', tool: tool as never, args });
const EMPTY_V = 'namespace Demo\n\nend Demo\n';
const VOC = 'axiom Being : Type\naxiom Being.exists : Nonempty Being\ninstance : Nonempty Being := Being.exists\naxiom Human : Being → Prop\naxiom Mortal : Being → Prop\nnoncomputable opaque socrates : Being\n';
const stmts = (blank = ''): FakeStep[] => [
  edit(INBOX, B('All humans are mortal'), `${B('All humans are mortal')}${blank}/-- All humans are mortal -/\nabbrev all_humans_are_mortal : Prop := ∀ x : Being, Human x → Mortal x\naxiom all_humans_are_mortal.holds : all_humans_are_mortal\n`),
  edit(INBOX, B('Socrates is a human'), `${B('Socrates is a human')}/-- Socrates is a human -/\nabbrev socrates_is_a_human : Prop := Human socrates\naxiom socrates_is_a_human.holds : socrates_is_a_human\n`),
  edit(INBOX, B('Socrates is mortal', P), `${B('Socrates is mortal', P)}/-- Socrates is mortal -/\nabbrev socrates_is_mortal : Prop := Mortal socrates\n`),
];
const PROOF = 'theorem socrates_is_mortal.holds : socrates_is_mortal :=\n  all_humans_are_mortal.holds socrates socrates_is_a_human.holds\n';
const proveAfterTarget = edit(INBOX, 'abbrev socrates_is_mortal : Prop := Mortal socrates\n', `abbrev socrates_is_mortal : Prop := Mortal socrates\n${PROOF}`);
const tail: FakeStep[] = [call('check_lean', {}), call('finish', { status: 'proved', summary: 'ok', assumed_without_asking: [] }), { kind: 'result' }];

const VARIANTS: Record<string, FakeStep[]> = {
  // V1: the vocabulary at the top of Inbox.lean (not Vocabulary.lean)
  vocabInInbox: [
    edit(INBOX, '-- New cards typed on the telelean board are added here.\nnamespace Demo\n\n', `-- New cards typed on the telelean board are added here.\nnamespace Demo\n\n${VOC}\n`),
    ...stmts(),
    call('check_lean', {}),
    call('freeze_statements', { targets: ['socrates-is-mortal'] }),
    proveAfterTarget,
    ...tail,
  ],
  // V2: a named presupposition instance, no docstrings anywhere
  namedInstance: [
    edit(VOCAB, EMPTY_V, `namespace Demo\n\n${VOC.replace('instance : Nonempty Being', 'instance instNonemptyBeing : Nonempty Being')}\nend Demo\n`),
    ...stmts().map((s) => (s.kind === 'edit' ? { ...s, newString: s.newString.replace(/\/-- [^\n]* -\/\n/, '') } : s)),
    call('check_lean', {}),
    call('freeze_statements', { targets: ['socrates-is-mortal'] }),
    proveAfterTarget,
    ...tail,
  ],
  // V4: the proof in Main.lean (which imports Inbox)
  proofInMain: [
    edit(VOCAB, EMPTY_V, `namespace Demo\n\n${VOC}\nend Demo\n`),
    ...stmts(),
    call('check_lean', {}),
    call('freeze_statements', { targets: ['socrates-is-mortal'] }),
    edit(MAIN, 'namespace Demo\n\nend Demo\n', `namespace Demo\n\n${PROOF}\nend Demo\n`),
    ...tail,
  ],
  // V3: a blank line between a block and its statement, then fixed after the refusal
  blankLine: [
    edit(VOCAB, EMPTY_V, `namespace Demo\n\n${VOC}\nend Demo\n`),
    ...stmts('\n'),
    call('check_lean', {}),
    call('freeze_statements', { targets: ['socrates-is-mortal'] }),
    edit(INBOX, `${B('All humans are mortal')}\n`, B('All humans are mortal')),
    call('freeze_statements', { targets: ['socrates-is-mortal'] }),
    proveAfterTarget,
    ...tail,
  ],
  // V5: statements as `def` with the value on the next line; a tactic proof with intro/apply
  defStatements: [
    edit(VOCAB, EMPTY_V, `namespace Demo\n\n${VOC}\nend Demo\n`),
    ...stmts().map((s) => (s.kind === 'edit' ? { ...s, newString: s.newString.replace(/abbrev (\w+) : Prop := /g, 'def $1 : Prop :=\n  ') } : s)),
    call('check_lean', {}),
    call('freeze_statements', { targets: ['socrates-is-mortal'] }),
    edit(INBOX, 'def socrates_is_mortal : Prop :=\n  Mortal socrates\n', 'def socrates_is_mortal : Prop :=\n  Mortal socrates\ntheorem socrates_is_mortal.holds : socrates_is_mortal := by\n  unfold socrates_is_mortal\n  exact all_humans_are_mortal.holds socrates socrates_is_a_human.holds\n'),
    ...tail,
  ],
  // V6: the constant without the presupposition first (Lean error), then fixed
  forgotPresupposition: [
    edit(VOCAB, EMPTY_V, 'namespace Demo\n\naxiom Being : Type\naxiom Human : Being → Prop\naxiom Mortal : Being → Prop\nnoncomputable opaque socrates : Being\n\nend Demo\n'),
    ...stmts(),
    call('check_lean', {}),
    edit(VOCAB, 'axiom Being : Type\n', 'axiom Being : Type\naxiom Being.exists : Nonempty Being\ninstance : Nonempty Being := Being.exists\n'),
    call('check_lean', {}),
    call('freeze_statements', { targets: ['socrates-is-mortal'] }),
    proveAfterTarget,
    ...tail,
  ],
};

describe('variants', () => {
  for (const [name, steps] of Object.entries(VARIANTS)) {
    if (process.env['VARIANT'] !== undefined && process.env['VARIANT'] !== name) continue;
    it(name, async () => {
      const dir = makeTempDir(`var-${name}`);
      const root = path.join(dir, 'demo');
      mkdirSync(root);
      await fsEditApplier(root).apply(planInitialize({ subject: 'Demo', inspection: await inspectFolder(root) }), 'Initialize model');
      const ws = createModelWorkspace({ root, text: fsTextSource(root), applier: fsEditApplier(root), semantic: { debounceMs: 60_000 }, now: () => new Date('2026-11-10T12:00:00Z') });
      await ws.load();
      for (const [type, naturalName] of [['ASSUMPTION', 'All humans are mortal'], ['ASSUMPTION', 'Socrates is a human'], ['GOAL', 'Socrates is mortal']] as const) await ws.perform({ kind: 'add-node', subject: 'Demo', type, naturalName });
      await ws.refreshNow();
      const play = playFakeScript([{ match: 'Run: "These suffice"', steps }]);
      const runsDir = path.join(dir, 'runs');
      const manager = createRunManager({ root, runsDir, workspace: ws, services: { backend: new FakeBackend(play.script), engine: createLeanCheckEngine(), proposals: createProposalService(), sidecars: createRunSidecarStore() }, settings: DEFAULT_RUN_SETTINGS });
      await manager.start({ subject: 'Demo', target: 'socrates-is-mortal', premises: ['all-humans-are-mortal', 'socrates-is-a-human'] });
      const end = await waitForRun(manager, (v) => v.state === 'review' || v.state === 'failed', 300_000);
      const runDir = (await listRunDirs(runsDir, root)).find((d) => d.runId === end.runId)?.runDir ?? '';
      const results = readFileSync(path.join(runDir, 'session', 'transcript.jsonl'), 'utf8').trim().split('\n').map((l) => JSON.parse(l) as { kind: string; event?: LlmEvent }).filter((e) => e.kind === 'event' && e.event?.type === 'tool_result').map((e) => (e.event as { text: string }).text).filter((t) => !t.startsWith('edited'));
      const p = manager.proposal();
      let accepted = 'n/a';
      let graph = '';
      if (p) {
        accepted = JSON.stringify(await manager.accept(end.runId, p.proposalId, p.lifecycle.map((l) => l.id), p.definitions.map((d) => d.id)));
        await ws.refreshNow();
        graph = JSON.stringify(ws.graph('Demo').nodes.map((n) => [n.id, n.type, n.status.formal, n.status.proof.kind, n.lean.binding]));
      }
      console.log(`### ${name}: ${end.state} ${end.verdict} defs=${JSON.stringify(p?.definitions.map((d) => d.name))} accept=${accepted}\n${graph}\n${results.join('\n---\n')}`);
      await manager.dispose();
      ws.dispose();
    });
  }
});

