            if c == '(' and i > 0 and s[i - 1] == '=':  # array assignment a=( ... )
                j = find_close(s, i + 1)
                cur.append(s[i:j + 1]); i = j + 1; continue
            flush(); i += 1; continue
        cur.append(c); i += 1
